"""Tests for the generated safety_audit_brief_final.hwpx"""
import json
import re
import zipfile
from pathlib import Path

import pytest

FINAL_PATH = Path("/root/safety_audit_brief_final.hwpx")


def test_file_exists():
    assert FINAL_PATH.exists(), "Final HWPX file must exist"


def test_valid_zip():
    with zipfile.ZipFile(FINAL_PATH, 'r') as zf:
        assert zf.testzip() is None, "ZIP must be valid"
        names = zf.namelist()
        assert "Contents/section0.xml" in names
        assert "Contents/section1.xml" in names
        assert "Contents/content.hpf" in names


def test_no_duplicate_entries():
    with zipfile.ZipFile(FINAL_PATH, 'r') as zf:
        names = zf.namelist()
        assert len(names) == len(set(names)), "No duplicate ZIP entries allowed"


class TestSection0:
    @pytest.fixture(scope="class")
    def content(self):
        with zipfile.ZipFile(FINAL_PATH, 'r') as zf:
            return zf.read("Contents/section0.xml").decode('utf-8')

    def test_no_placeholders_remain(self, content):
        assert "{{" not in content
        assert "}}" not in content

    def test_inspection_id(self, content):
        assert "SAF-26-041" in content

    def test_site_name(self, content):
        assert "부산 서부 냉장 창고" in content

    def test_inspector(self, content):
        assert "김도윤" in content

    def test_date_format(self, content):
        assert "2026.06.18" in content
        assert "2026-06-18" not in content

    def test_risk_tier_with_severity(self, content):
        assert "High (즉시조치)" in content
        # Ensure both occurrences (table + confirmation line) are replaced
        assert content.count("High (즉시조치)") >= 2

    def test_overall_opinion(self, content):
        assert "하역 구역 동선 분리가 미완료되어 즉시 조치가 필요합니다." in content

    def test_linesegarray_removed(self, content):
        assert "<hp:linesegarray>" not in content

    def test_titles_preserved(self, content):
        assert "창고 안전 점검 브리프" in content
        assert "현장명" in content
        assert "주관 점검자" in content
        assert "점검일" in content
        assert "위험 등급" in content


class TestSection1:
    @pytest.fixture(scope="class")
    def content(self):
        with zipfile.ZipFile(FINAL_PATH, 'r') as zf:
            return zf.read("Contents/section1.xml").decode('utf-8')

    def test_no_placeholders_remain(self, content):
        assert "{{" not in content
        assert "}}" not in content

    def test_action_1(self, content):
        assert "지게차 충전 구역 주변 적치물을 오늘 안에 제거" in content

    def test_action_2(self, content):
        assert "보행자 동선을 바닥 표시로 재구획" in content

    def test_action_3(self, content):
        assert "야간 근무조 대상 안전 브리핑을 재실시" in content

    def test_report_target(self, content):
        assert "권역 운영실장" in content

    def test_linesegarray_removed(self, content):
        assert "<hp:linesegarray>" not in content

    def test_title_preserved(self, content):
        assert "즉시 조치 항목" in content

    def test_actions_order(self, content):
        # Actions must appear in the same order as corrective_actions.json
        idx1 = content.find("지게차 충전 구역 주변 적치물을 오늘 안에 제거")
        idx2 = content.find("보행자 동선을 바닥 표시로 재구획")
        idx3 = content.find("야간 근무조 대상 안전 브리핑을 재실시")
        assert idx1 < idx2 < idx3, "Actions must appear in JSON order"

    def test_note_preserved(self, content):
        assert "비고: 사진 부록은 별도 보관" in content

